body{margin:0;font-family:'Baloo 2',-apple-system,BlinkMacSystemFont,'PingFang SC','Hiragino Sans GB','Microsoft YaHei','HarmonyOS Sans SC','MiSans',system-ui,sans-serif;background:#141312;color:#F2EFEA}
